// P1-fix (issue 12): JSON-escape a string for safe inclusion in a JSON string
// literal. Escapes ", \, control chars (<0x20) as \uXXXX. Previously reason
// fields were concatenated raw into writeStateJson's output; internal reasons
// are static ASCII so this was latent, but any future dynamic reason (from
// control commands, eBPF errors, etc.) would break JSON parsing on the WebUI.
static std::string jsonEscape(const std::string& s) {
    std::string out;
    out.reserve(s.size() + 8);
    for (char c : s) {
        unsigned char uc = (unsigned char)c;
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (uc < 0x20) {
                    char buf[8];
                    snprintf(buf, sizeof(buf), "\\u%04x", uc);
                    out += buf;
                } else {
                    out += c;
                }
        }
    }
    return out;
}

